"""Migration utilities for Meridian CRM AUD_EVENT records."""

from __future__ import annotations


def migrate_event(row: dict) -> dict:
    """Convert one legacy AUD_EVENT row to its modern event representation."""
    timestamp = row["EVT_TS"]
    return {
        "evt_id": int(row["EVT_ID"]),
        "ts": (
            f"{timestamp[0:4]}-{timestamp[4:6]}-{timestamp[6:8]}"
            f"T{timestamp[8:10]}:{timestamp[10:12]}:{timestamp[12:14]}"
        ),
        "code": row["EVT_CD"],
        "user_id": row["USR_ID"],
        "entity": row["ENT_NAME"],
        "entity_id": row["ENT_ID"],
        "old_val": row["OLD_VAL"],
        "new_val": row["NEW_VAL"],
    }


class AuditStore:
    """An in-memory append-only audit event store."""

    def __init__(self) -> None:
        self._events: list[dict] = []
        self._event_ids: set[int] = set()

    def append(self, event: dict) -> None:
        """Append an event unless its evt_id is already present."""
        event_id = event["evt_id"]
        if event_id in self._event_ids:
            return

        self._events.append(event.copy())
        self._event_ids.add(event_id)

    def events(self) -> list[dict]:
        """Return a defensive copy of the stored events."""
        return [event.copy() for event in self._events]

    def __len__(self) -> int:
        return len(self._events)


def migrate(rows: list[dict], store: AuditStore | None = None) -> AuditStore:
    """Migrate rows in canonical EVT_ID order into an append-only store."""
    if store is None:
        store = AuditStore()

    for row in sorted(rows, key=lambda item: int(item["EVT_ID"])):
        store.append(migrate_event(row))

    return store
